/bin/zsh -lc "cat > src/orchestration/tools/registry.test.ts <<'EOF'
import {ToolRegistry} from './registry.js';

describe('ToolRegistry', () => {
  // specs/hal-engine-tool-input-validation/spec.md#5
  it('rejects an invalid static schema at registration naming the tool', () => {
    const registry = new ToolRegistry();

    expect(() =>
      registry.register(
        {name: 'weather', description: 'Weather', inputSchema: {type: 'invalid'}},
        async () => 'sunny'
      )
    ).toThrow(/weather/);
  });
});
EOF
